import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.D1K3FKSn.js";const u=JSON.parse('{"title":"URL parameters","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/guide/url-parameters.html"}],["meta",{"property":"og:title","content":"URL parameters | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/guide/url-parameters.html"}],["meta",{"name":"twitter:title","content":"URL parameters | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/url-parameters.md","filePath":"guide/url-parameters.md"}'),r={name:"guide/url-parameters.md"};function c(i,t,s,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="url-parameters" tabindex="-1">URL parameters <a class="header-anchor" href="#url-parameters" aria-label="Permalink to &quot;URL parameters&quot;">​</a></h1><p>Control rendering settings via URL parameters to share or bookmark specific views.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>dataset</code></td><td>URL</td><td>Volume data source</td><td><code>dataset=https://...volume.ome.zarr</code></td></tr><tr><td><code>mode</code></td><td><code>dvr</code>, <code>mip</code>, <code>iso</code>, <code>lod</code>, <code>slice</code></td><td>Render mode</td><td><code>mode=mip</code></td></tr><tr><td><code>wc</code></td><td>0-1</td><td>Window center</td><td><code>wc=0.35</code></td></tr><tr><td><code>ww</code></td><td>0-1</td><td>Window width</td><td><code>ww=0.55</code></td></tr><tr><td><code>iso</code></td><td>0-1</td><td>Isosurface threshold</td><td><code>iso=0.15</code></td></tr><tr><td><code>tf</code></td><td><code>grayscale</code>, <code>grayscale-inverted</code>, <code>coolwarm</code>, <code>hot</code>, <code>cool</code>, <code>viridis</code>, <code>plasma</code>, <code>seismic</code></td><td>Transfer function preset</td><td><code>tf=coolwarm</code></td></tr><tr><td><code>tfpts</code></td><td>x,y pairs</td><td>TF opacity control points (comma-separated)</td><td><code>tfpts=0,0,0.5,0.8,1,1</code></td></tr><tr><td><code>up</code></td><td><code>x</code>, <code>y</code>, <code>z</code>, <code>-x</code>, <code>-y</code>, <code>-z</code></td><td>Camera up axis</td><td><code>up=-y</code></td></tr><tr><td><code>scale</code></td><td>0.25-1.0</td><td>Render resolution</td><td><code>scale=1.0</code></td></tr><tr><td><code>cam</code></td><td>6 numbers</td><td>Camera state (rotation, distance, target)</td><td><code>cam=0.1,2.3,3.5,0,0,0</code></td></tr><tr><td><code>clipMin</code></td><td>x,y,z</td><td>Clipping min (normalised 0–1)</td><td><code>clipMin=0.2,0.1,0</code></td></tr><tr><td><code>clipMax</code></td><td>x,y,z</td><td>Clipping max (normalised 0–1)</td><td><code>clipMax=0.8,0.9,1</code></td></tr><tr><td><code>slices</code></td><td>x,y,z</td><td>Slice plane positions (normalised 0–1, only used in <code>slice</code> mode)</td><td><code>slices=0.5,0.5,0.5</code></td></tr><tr><td><code>sliceVis</code></td><td>0–7</td><td>Slice plane visibility bitmask (bit 0=X, 1=Y, 2=Z; default 7 = all visible)</td><td><code>sliceVis=3</code></td></tr><tr><td><code>wireframe</code></td><td><code>1</code></td><td>Enable bounding box wireframe overlay</td><td><code>wireframe=1</code></td></tr><tr><td><code>axis</code></td><td><code>1</code></td><td>Enable world-space axis overlay</td><td><code>axis=1</code></td></tr></tbody></table><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>?dataset=https://example.com/scan.ome.zarr&amp;mode=mip&amp;wc=0.2&amp;ww=0.3&amp;tf=coolwarm</span></span></code></pre></div><p>The <strong>Share</strong> button (top-right of the demo) copies the current view as a URL with all parameters filled in.</p><blockquote><p>Multichannel datasets use a different set of URL parameters (per-channel colour, windowing, and visibility). See <a href="/rendering/multichannel.html#url-parameters">Multichannel → URL parameters</a>.</p></blockquote>',7)])])}const h=e(r,[["render",c]]);export{u as __pageData,h as default};
